import{_ as i,C as a,o,c as l,a6 as s,E as t}from"./chunks/framework.5dd0l9Wo.js";const w=JSON.parse('{"title":"Essential Skills","description":"Targeted scanning, request replay, and reading non-standard data structures without prior knowledge.","frontmatter":{"title":"Essential Skills","description":"Targeted scanning, request replay, and reading non-standard data structures without prior knowledge."},"headers":[],"relativePath":"essential-skills/index.md","filePath":"essential-skills/index.md"}'),d={name:"essential-skills/index.md"};function c(h,e,p,u,m,g){const n=a("LabGroup"),r=a("TopicComplete");return o(),l("div",null,[e[0]||(e[0]=s('<h1 id="essential-skills" tabindex="-1">Essential Skills <a class="header-anchor" href="#essential-skills" aria-label="Permalink to &quot;Essential Skills&quot;">​</a></h1><p class="wd-section-lede">The exam and real assessments do not tell you the vulnerability class. The skill is a loop: observe, form a hypothesis, make the smallest request that distinguishes it from the alternatives, then escalate.</p><div class="wd-callout"><p><strong>The model.</strong> Recon is not a scanner run. It is a sequence of <em>discriminating</em> requests. Each request should answer one question: which parser, which framework, which parameter reaches which sink, which control is enforced where.</p></div><h2 id="a-repeatable-loop" tabindex="-1">A repeatable loop <a class="header-anchor" href="#a-repeatable-loop" aria-label="Permalink to &quot;A repeatable loop&quot;">​</a></h2><ol><li><strong>Map the surface.</strong> Crawl, read JavaScript, list parameters, note roles and state changes.</li><li><strong>Establish a baseline.</strong> Capture a normal request and its exact response — status, length, timing, headers.</li><li><strong>Perturb one thing.</strong> A quote, a traversal, a duplicate parameter, a method change, an extra JSON field.</li><li><strong>Compare.</strong> A difference is a lead; no difference is information too.</li><li><strong>Escalate with intent.</strong> Turn the difference into a read, a write, or code execution. Stop when you can prove impact.</li></ol><details class="details custom-block"><summary>🔬 Under the Hood: why targeted scanning beats full scanning</summary><p>A scanner sends many payloads and reports signatures. It is good at known patterns and bad at logic, chained bugs, and application-specific sinks. Targeted scanning uses the scanner as a <em>hypothesis generator</em> on a specific parameter, then a human (or a focused script) verifies the anomaly.</p><p>The workflow is: identify a likely sink from behaviour, send a small set of payloads that would produce distinct responses, and inspect the raw response rather than the scanner&#39;s severity label.</p></details><h2 id="non-standard-data-structures" tabindex="-1">Non-standard data structures <a class="header-anchor" href="#non-standard-data-structures" aria-label="Permalink to &quot;Non-standard data structures&quot;">​</a></h2><p>Not every input is <code>application/x-www-form-urlencoded</code>. Look for:</p><ul><li>JSON with nested objects and arrays;</li><li>XML/SOAP envelopes;</li><li>serialized blobs (base64, PHP, Java, .NET);</li><li>multipart bodies with unusual field names;</li><li>custom binary protocols over WebSockets;</li><li>GraphQL with aliases and fragments.</li></ul><p>The parser is the attack surface. If you do not know the format, change one structural element and watch the error: the error names the parser.</p>',10)),t(n,{ids:"essential-skills-lab-discovering-vulnerabilities-quickly-with-targeted-scanning, essential-skills-lab-scanning-non-standard-data-structures"}),e[1]||(e[1]=s('<details class="details custom-block"><summary>⚙️ Engine Variations: error-driven fingerprinting</summary><ul><li><strong>JSON parsers</strong> return position-aware messages (<code>Unexpected token } in JSON at position 42</code>).</li><li><strong>XML parsers</strong> name the line and column, and sometimes the DTD.</li><li><strong>Java deserialization</strong> throws <code>InvalidClassException</code> with the class name.</li><li><strong>PHP</strong> warns with the file and line, or returns a blank 500 if display_errors is off.</li><li><strong>GraphQL</strong> returns <code>errors</code> with <code>locations</code> and <code>path</code>, and suggestions for unknown fields.</li></ul><p>Read the error, then choose the next request. The error is a description of the parser&#39;s grammar.</p></details><div class="wd-callout"><p><strong>Practice.</strong> Take any lab in this portal and write down the one request that would distinguish its vulnerability class from the two most likely alternatives. If you cannot name that request, you do not yet understand the mechanism.</p></div>',2)),t(r,{"topic-id":"essential-skills",label:"Mark essential skills complete"})])}const k=i(d,[["render",c]]);export{w as __pageData,k as default};
